91	                     (content_hash, file_path, mtime_ns, byte_size, token_count,
92	                      session_id, created_at, last_hit_at, hit_count)
93	                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?7, 1)",
94	                    params![
95	                        hash,
96	                        file_path,
97	                        current_mtime_ns as i64,
98	                        content.len() as i64,
99	                        token_count as i64,
100	                        self.session_id,
101	                        now as i64,
102	                    ],
103	                )?;
104	                self.evict_if_needed()?;
105	                Ok(DedupResult {
106	                    cache_hit: false,
107	                    content_hash: hash,
108	                    tokens_saved: 0,
109	                    summary: None,
110	                })
111	            }
112	        }
113	    }
